class Solution:
    def closestToTarget(self, arr: List[int], target: int) -> int:
        n = len(arr)
        ans = float('inf')
        for l in range(n):
            cur = (1 << 20) - 1
            for r in range(l, n):
                cur &= arr[r]
                ans = min(ans, abs(cur - target))
        return ans

