        ans = float('inf')
        vals = []
        for x in arr:
            vals = [x] + [v & x for v in vals]
            vals = [v for i, v in enumerate(vals) if i == 0 or v != vals[i - 1]]
            ans = min(ans, min(abs(v - target) for v in vals))
