class Solution {
public:
    int closestToTarget(vector<int>& arr, int target) {
        long long ans = LLONG_MAX;
        vector<int> vals;
        for (int x : arr) {
            vector<int> nxt;
            nxt.reserve(vals.size() + 1);
            nxt.push_back(x);
            for (int v : vals) {
                int w = v & x;
                if (w != nxt.back()) nxt.push_back(w);
            }
            vals.swap(nxt);
            for (int v : vals) ans = min(ans, (long long)abs(v - target));
        }
        return (int)ans;
    }
};

