class Solution {
    public int closestToTarget(int[] arr, int target) {
        long ans = Long.MAX_VALUE;
        List<Integer> vals = new ArrayList<>();
        for (int x : arr) {
            List<Integer> nxt = new ArrayList<>();
            nxt.add(x);
            for (int v : vals) {
                int w = v & x;
                if (w != nxt.get(nxt.size() - 1)) nxt.add(w);
            }
            vals = nxt;
            for (int v : vals) ans = Math.min(ans, Math.abs((long) v - target));
        }
        return (int) ans;
    }
}

